#include <iostream>
#include <vector>
#include <map>
#include <bitset>
using namespace std;

const int MOD = 1000000007;

struct ModNumber {
    int val;

    ModNumber(long long v = 0) {
        v %= MOD;
        if (v < 0) v += MOD;
        val = v;
    }

    static int modInverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return val; }

    ModNumber& operator+=(const ModNumber& other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }

    ModNumber& operator-=(const ModNumber& other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }

    ModNumber& operator*=(const ModNumber& other) {
        val = (uint64_t)val * other.val % MOD;
        return *this;
    }

    ModNumber& operator/=(const ModNumber& other) {
        return *this *= ModNumber(modInverse(other.val));
    }

    friend ModNumber operator+(const ModNumber& a, const ModNumber& b) { return ModNumber(a) += b; }
    friend ModNumber operator-(const ModNumber& a, const ModNumber& b) { return ModNumber(a) -= b; }
    friend ModNumber operator*(const ModNumber& a, const ModNumber& b) { return ModNumber(a) *= b; }
    friend ModNumber operator/(const ModNumber& a, const ModNumber& b) { return ModNumber(a) /= b; }

    ModNumber& operator++() {
        val = (val == MOD - 1) ? 0 : val + 1;
        return *this;
    }

    ModNumber& operator--() {
        val = (val == 0) ? MOD - 1 : val - 1;
        return *this;
    }

    ModNumber operator++(int) { ModNumber tmp = *this; ++(*this); return tmp; }
    ModNumber operator--(int) { ModNumber tmp = *this; --(*this); return tmp; }

    ModNumber operator-() const {
        return val == 0 ? 0 : MOD - val;
    }

    bool operator==(const ModNumber& other) const { return val == other.val; }
    bool operator!=(const ModNumber& other) const { return val != other.val; }

    ModNumber inv() const {
        return ModNumber(modInverse(val));
    }

    ModNumber pow(long long p) const {
        ModNumber base = *this, result = 1;
        while (p > 0) {
            if (p & 1) result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

int main() {
    int N;
    cin >> N;
    vector<vector<ModNumber>> prob(N, vector<ModNumber>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            int p;
            cin >> p;
            prob[i][j] = ModNumber(p) / ModNumber(100);
        }

    vector<vector<int>> count_masks(N + 1);
    vector<int> lookup(1 << N, -1);
    for (int m = 0; m < (1 << N); ++m) {
        int c = __builtin_popcount(m);
        lookup[m] = (int)count_masks[c].size();
        count_masks[c].push_back(m);
    }

    map<long long, ModNumber> current_masks;
    current_masks[1LL << lookup[0]] = 1;

    for (int l = 0; l < N; ++l) {
        map<long long, ModNumber> next_masks;
        for (int mask = 0; mask < (1 << N); ++mask) {
            ModNumber prod = 1;
            for (int r = 0; r < N; ++r) {
                bool bit_set = (mask >> r) & 1;
                prod *= bit_set ? prob[l][r] : (ModNumber(1) - prob[l][r]);
            }
            for (auto& p : current_masks) {
                long long msk = p.first;
                ModNumber pval = p.second;
                long long new_msk = 0;
                for (int m : count_masks[l]) {
                    if ((msk >> lookup[m]) & 1) {
                        for (int i = 0; i < N; ++i) {
                            if (((mask >> i) & 1) && ((m >> i) & 1) == 0) {
                                new_msk |= 1LL << lookup[m | (1 << i)];
                            }
                        }
                    }
                }
                next_masks[new_msk] += pval * prod;
            }
        }
        current_masks = move(next_masks);
    }

    ModNumber total = 0;
    int last_idx = lookup[(1 << N) - 1];
    for (auto& p : current_masks) {
        if ((p.first >> last_idx) & 1) total += p.second;
    }
    cout << (int)total << "\n";
}
